"""Source-only Korean data-preparation report; never reads model/eval scores."""
from pathlib import Path
import base64,datetime,hashlib,html,json
import numpy as np
from PIL import Image

ROOT=Path(__file__).resolve().parents[1]
ASSETS=ROOT/'source_audit/DATA_PREPARATION_REPORT'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def bind(p):return dict(path=str(Path(p).resolve()),sha256=sha(p))
def read(n):return json.loads((ROOT/n).read_text())
def uri(p):return 'data:image/png;base64,'+base64.b64encode(Path(p).read_bytes()).decode()
def link(n,label=None):return '<a href="'+html.escape(str((ROOT/n).resolve()),quote=True)+'">'+html.escape(label or n)+'</a>'
def image(n,alt,cls=''):return '<img class="'+cls+'" src="'+uri(ROOT/n)+'" alt="'+html.escape(alt,quote=True)+'">'
def pct(n,total):return round(n/total*100,2)
def write(p,d):
 with Path(p).open('x')as f:json.dump(d,f,ensure_ascii=False,indent=2,allow_nan=False);f.write('\n')

def main():
 if (ROOT/'DATA_PREPARATION_KO.html').exists()or (ROOT/'DATA_PREPARATION_KO.json').exists():raise FileExistsError('Preserve existing report snapshot')
 ASSETS.mkdir(exist_ok=False)
 generated=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=9))).isoformat(timespec='seconds')
 intake=read('public_pallet/INTAKE_ADMISSION_STATUS.json');paired=read('public_pallet/PAIRED_QUERIES/SEAL.json');controlled=read('controlled/SEAL.json')
 audit=read('source_audit/CONTROLLED_INDEPENDENT_AUDIT.json');joined=read('source_audit/JOINED_CACHE_AUDIT.json');family=read('provenance/EVALUATION_FAMILY_PROVENANCE.json')
