 rows=[json.loads(s)for s in (ROOT/'public_pallet/PAIRED_QUERIES/INPUTS_RGB_ONLY.jsonl').read_text().splitlines()]
 states={}
 for split,file in [('TRAIN','PALLOX_TRAIN.npz'),('VALIDATION','PALLOX_VAL.npz')]:
  with np.load(ROOT/'public_pallet/PAIRED_QUERIES'/file,allow_pickle=False)as z:
   for i,s in enumerate(z['sample_id']):states[str(s)]=dict(exact=int(z['dense_exact_state'][i,4,4]),near=int(z['dense_radius2_state'][i,4,4]),allowed=int(z['dense_allowed'][i,4,4]),valid=bool(z['dense_valid'][i,4,4]))
 cases=[]
 for session in ('0.55m_hall','0.55m_lab','1.23m_hall','1.23m_lab','1.92m_hall','1.92m_lab'):
  chosen=[r for r in rows if r['group_id']==f'PALLOXPAIR:{session}:0000_0001'];assert len(chosen)==2
  views=[]
  for r in sorted(chosen,key=lambda z:z['id']):
   q=np.asarray(r['query'][0],np.float64);p=np.floor(q+.5).astype(int)
   with Image.open(r['image'])as im:crop=im.convert('RGB').crop((p[0]-48,p[1]-48,p[0]+48,p[1]+48))
   out=ASSETS/(session+'_'+r['id'][-1]+'_QUERY0_NATIVE96.png');crop.save(out)
   views.append(dict(view=r['id'][-1],id=r['id'],query=q.tolist(),nearest_pixel=p.tolist(),crop=bind(out),source_image=dict(path=r['image'],sha256=r['image_sha256']),**states[r['id']+':0']))
  assert views[0]['query']==views[1]['query']
  cases.append(dict(session=session,split=chosen[0]['split'],slot=0,views=views))
 write(ASSETS/'FIXED_NATIVE_CROP_SELECTION.json',dict(selection='Literal0000_0001 pair per six source sessions; fixed slot0 actual jittered query; no model scores',native_size=96,rounding='floor(query+.5), [p-48,p+48), black outside canvas',cases=cases))
